                'length': 150
            }
        }
        self.number_of_documents = len(self.documents)

    def get_urls(self, keyword: str) -> list[str]:
        urls = []
        for url, document in self.documents.items():
            if keyword in document['content'].lower():
                urls.append(url)
        return urls

    def idf(self, keyword: str) -> float:
        N = self.number_of_documents
        n_kw = len(self.get_urls(keyword))
        return log((N - n_kw + 0.5) / (n_kw + 0.5) + 1)

    def tf(self, keyword: str, url: str) -> float:
        document = self.documents[url]
        return document['content'].lower().count(keyword) / document['length']

